import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"The React report — section contract","description":"The contract a section of the React report must satisfy — the v6 page structure, the register completeness rule, and how an assessment is added without touching the shell.","frontmatter":{"description":"The contract a section of the React report must satisfy — the v6 page structure, the register completeness rule, and how an assessment is added without touching the shell."},"headers":[],"relativePath":"reference/react-report-section-contract.md","filePath":"reference/react-report-section-contract.md"}'),n={name:"reference/react-report-section-contract.md"};function o(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-react-report-—-section-contract" tabindex="-1">The React report — section contract <a class="header-anchor" href="#the-react-report-—-section-contract" aria-label="Permalink to &quot;The React report — section contract&quot;">​</a></h1><p><strong>Status:</strong> normative. Work item <strong>AB#6936</strong> (the React report framework), Feature AB#6928. Describes the <strong>v6</strong> information architecture shipped in v3.5.0.</p><div class="danger custom-block"><p class="custom-block-title">The React report is the one supported deliverable</p><p>Word, PDF, Excel, PowerPoint, Power BI, the standalone HTML renderer and the Markdown-file renderer are <strong>on hold</strong> (<strong>AB#6922</strong>) and are not emitted. They are being rebuilt to generate <em>from</em> this report rather than alongside it. Export to Markdown, JSON, CSV, PDF (print) or a standalone HTML copy <strong>from the report page itself</strong>. <code>Json</code> / <code>JsonEvidence</code> are data, not documents, and are never held. See <a href="./../assessment/configuration.html#report-tiers">Report tiers</a>.</p></div><p>This is the contract a report section must satisfy. It exists so that <strong>adding an assessment is a payload change plus, at most, one registered renderer — never an edit to the shell</strong>.</p><p>If you find yourself editing navigation, view depth, theming, export, or the diagram kernel in order to add an assessment, the contract has been broken. Fix the contract, not the shell.</p><hr><h2 id="_1-the-information-architecture-v6" tabindex="-1">1. The information architecture (v6) <a class="header-anchor" href="#_1-the-information-architecture-v6" aria-label="Permalink to &quot;1. The information architecture (v6)&quot;">​</a></h2><p>The report is a <strong>multi-page application inside one self-contained HTML file</strong>. Page visibility is driven by <code>data-page</code> on <code>&lt;body&gt;</code>; there is no routing, no fetch, and no second file. The top nav is built from what actually ran — a page whose data is absent is not offered.</p><table tabindex="0"><thead><tr><th>Page</th><th><code>data-page</code></th><th>What it carries</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td><code>ov</code></td><td>The collection-details strip (scope, tenant, timings, what was skipped and why — a strip on this page, <strong>not</strong> a global banner), the lede and KPI row, menu tiles into every other page, one gauge tile per assessment, and a single &quot;act on this first&quot; spotlight.</td></tr><tr><td><strong>Inventory &amp; audit</strong></td><td><code>inv</code></td><td>A blade sidebar over the estate — see §2.</td></tr><tr><td><strong>Assessments</strong></td><td><code>as</code></td><td>Landing tiles: gauge, verdict sentence, area preview, pass/fail/manual counts. Each tile opens a per-assessment page.</td></tr><tr><td><strong>Per-assessment</strong></td><td><code>a-&lt;slug&gt;</code></td><td>The full conformance register for one assessment — see §3.</td></tr><tr><td><strong>Diagrams</strong></td><td><code>dgm</code></td><td>Blade-navigated figures: management-group hierarchy, VNets and subnets with IP-utilisation bars, estate top-10 bars, gaps-by-area severity bars. Each figure has a KPI context strip and a lede; nodes click through to the underlying blade; ⛶ opens a full-screen overlay with wheel zoom, drag pan, Fit and Esc. All inline SVG.</td></tr><tr><td><strong>Data &amp; drift</strong></td><td><code>data</code></td><td>The unabridged all-findings table (fails ranked first), the evidence table, cross-run drift KPIs and tables, and provenance.</td></tr><tr><td><strong>Remediation plan</strong></td><td><code>road</code></td><td>Every fail, twice: a 90-day plan by area, and workstreams by team with a t-shirt size. Rows link back to their gap blocks.</td></tr></tbody></table><p>Orthogonal to the pages, and owned by the shell:</p><ul><li><strong>View depth</strong> — Executive / Consultant / Data, set by <code>data-view</code> on <code>&lt;body&gt;</code>. This is a <em>depth</em> control, not a page: the same DOM, three amounts of it. Executive leads with the conclusion and a top-gaps summary; Consultant is the delivered engagement chapter; Data is everything, filterable and exportable, with nothing summarised away.</li><li><strong>Theme</strong> — light / dark, via CSS custom properties. Contrast floors are asserted, so a section must use the tokens rather than hard-coded colours.</li><li><strong>Export</strong> — Markdown, JSON, findings CSV, evidence CSV, Print/PDF, and a standalone HTML copy. Export walks the section registry; a section outside the registry silently vanishes from every export.</li></ul><h2 id="_2-the-inventory-blade-model" tabindex="-1">2. The inventory blade model <a class="header-anchor" href="#_2-the-inventory-blade-model" aria-label="Permalink to &quot;2. The inventory blade model&quot;">​</a></h2><p>The Inventory &amp; audit sidebar is <strong>the eighteen documented categories, in fixed order, under their Azure portal labels</strong> — the taxonomy is defined once in <a href="./category-structure.html">Category Structure</a> and must not be re-derived or reordered here.</p><ul><li>Payload keys map onto those eighteen by <code>keyCat()</code>: RBAC / PIM / classic administrators → <strong>Identity</strong>; <code>governance.*</code> → <strong>Management and governance</strong>; Log Analytics and operational posture → <strong>Monitor</strong>; <code>domains.&lt;x&gt;</code> → its own category; Advisor, subscriptions and tags → <strong>General</strong>.</li><li>Cost cleanup and FinOps datasets are <strong>not</strong> categories. They belong to the cost-optimization blade only.</li><li><strong>A zero is listed, not hidden.</strong> A category with no resources appears dimmed and opens an <em>absence</em> blade stating that the estate has none of that type — as distinct from the collector having failed, which the audit-callouts blade reports separately.</li><li>Group summary blades sit above the category blades; the Tenant structure blade carries the management-group tree and subscriptions; the Cost optimization blade carries the opportunity arithmetic, cost checks with links back to their fix, Advisor cost rows, the FinOps dataset table with an empty-reason per dataset, and the cleanup tables.</li><li>Category tables are filterable and sortable, bounded to a 480px scroll with a sticky header, and ellipsise at 80 characters with the full value on hover. Columns are chosen by density, not hard-coded per category.</li></ul><h2 id="_3-the-register-completeness-rule" tabindex="-1">3. The register completeness rule <a class="header-anchor" href="#_3-the-register-completeness-rule" aria-label="Permalink to &quot;3. The register completeness rule&quot;">​</a></h2><p><strong>This is the rule the report exists to satisfy.</strong> The owner&#39;s verdict on an earlier draft — <em>&quot;fancy marketing sites, not deep&quot;</em>, a page showing 2 of 139 checks — is why it is normative.</p><p>A per-assessment page is a <strong>complete conformance register</strong>, not a highlights reel:</p><ol><li><strong>Every check is listed.</strong> Passes, fails and manual checks all appear in the register table for their area. A check that ran and passed is evidence of work done; omitting it makes the report unfalsifiable.</li><li><strong>Every fail gets a gap block.</strong> Not the top five, not the criticals — every one. A gap block carries the evidence table (capped at 12 rows, with the true count stated), or the absence sentence where the finding <em>is</em> the absence; why it matters; a numbered fix; and the per-check Learn link.</li><li><strong>Every manual check is listed with the question it asks</strong>, in the area&#39;s manual agenda. A manual check is an interview item, not a gap in the report.</li><li><strong>Scores show their arithmetic.</strong> <code>percent</code> never appears without <code>formula</code>, <code>denominator</code> and <code>excludedCount</code> beside it — the Microsoft Secure Score pattern. The owner&#39;s review of an unexplained &quot;10/10&quot; is why this is non-negotiable.</li><li><strong>&quot;What&#39;s next&quot; closes the page</strong> — a START HERE item, then per-domain Action / Owner / Window rows, each linking back to the gap block it came from.</li></ol><p>Completeness must never regress for presentation. If a view depth needs to be shorter, it summarises <em>above</em> the register; it does not delete rows from it.</p><p>Page structure, in order: breadcrumb → banded gauge with its formula → area band panel → collapsible area chapters (register table → gap block per fail → manual agenda) → the Executive-depth top-gaps summary → What&#39;s next.</p><h2 id="_4-what-the-shell-owns-and-you-do-not-touch" tabindex="-1">4. What the shell owns, and you do not touch <a class="header-anchor" href="#_4-what-the-shell-owns-and-you-do-not-touch" aria-label="Permalink to &quot;4. What the shell owns, and you do not touch&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Owned by</th><th>Why you must not fork it</th></tr></thead><tbody><tr><td>Pages and nav</td><td><code>renderNav()</code> / <code>setPage()</code>, built from <code>ran</code></td><td>Nav is derived from what actually ran. A hand-added entry desynchronises from the payload.</td></tr><tr><td>View depth (Executive / Consultant / Data)</td><td><code>data-view</code> on <code>&lt;body&gt;</code></td><td>One DOM, three depths. A section that renders its own switch breaks print and export.</td></tr><tr><td>Theme / palette</td><td>CSS custom properties</td><td>Contrast is measured and asserted. Hard-coded colours bypass the WCAG floors.</td></tr><tr><td>Export (Markdown / JSON / CSV / Print / standalone HTML)</td><td>the export menu and the section registry</td><td>Export walks the registry; an unregistered section vanishes from every export.</td></tr><tr><td>Diagrams</td><td><code>window.__SCOUT_DIAGRAM_KERNEL__</code></td><td>The kernel guarantees no text/box overlap and no line routed through a box. Hand-rolled SVG is not collision-checked.</td></tr><tr><td>Escaping</td><td><code>esc()</code></td><td>Everything rendered is untrusted tenant data. See §7.</td></tr></tbody></table><h2 id="_5-the-payload-shape-a-section-receives" tabindex="-1">5. The payload shape a section receives <a class="header-anchor" href="#_5-the-payload-shape-a-section-receives" aria-label="Permalink to &quot;5. The payload shape a section receives&quot;">​</a></h2><p>Everything renders client-side from <code>window.__SCOUT_DATA__</code>, emitted by <code>src/report/renderers/Export-React.ps1</code>. An assessment entry in <code>assessments[]</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  slug, name, framework,</span></span>
<span class="line"><span>  scope:   { checksTotal, ... },</span></span>
<span class="line"><span>  areas:   [ { name, percent, formula, denominator, excludedCount, weight } ],</span></span>
<span class="line"><span>  findings:[ { id, title, severity, status, area, remediation,</span></span>
<span class="line"><span>               learnUrl, weight, evidenceCount,</span></span>
<span class="line"><span>               evidence: [ { resourceName, resourceId, subscriptionId, detail } ] } ]</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>Required of every section:</strong></p><ol><li><strong><code>slug</code> is the identity.</strong> Composite finding ids are <code>&quot;&lt;slug&gt;:&lt;ruleId&gt;&quot;</code>. Nav, deep links, the per-assessment <code>data-page</code> key, export filenames and the resource index all key off it. <code>areas[]</code> names are deduplicated by <code>(framework, name)</code> — two areas called &quot;Security&quot; is a payload defect, not something a section works around.</li><li><strong>Every field is optional at render time.</strong> Read through <code>safeArr()</code> / <code>dash()</code> / <code>Get-ReactSafeProp</code>. A section must render a defensible empty state, never throw. A section that throws takes the whole report down with it.</li><li><strong>Absence is a result, not a blank.</strong> Many rules are <code>exists</code> / <code>countGreaterThan</code> assertions that fail <em>precisely because</em> the query returned nothing — there is no resource to name and the finding <strong>is</strong> the absence. Say so in words. Never render an empty evidence table and leave the reader to guess whether the check was broken.</li></ol><h2 id="_6-the-depth-bar-consultant-view" tabindex="-1">6. The depth bar (Consultant view) <a class="header-anchor" href="#_6-the-depth-bar-consultant-view" aria-label="Permalink to &quot;6. The depth bar (Consultant view)&quot;">​</a></h2><p>Set by the reference deliverables. Per chapter:</p><ul><li>a <strong>domain scorecard</strong> with visible arithmetic;</li><li>a <strong>&quot;Current state&quot;</strong> paragraph per area, in prose, stating the score and what is open;</li><li><strong>findings grouped by area</strong>, not one flat list, priority-ordered (fails first, then severity);</li><li><strong>at least one figure</strong>, produced by the diagram kernel;</li><li><strong>evidence naming real resources</strong>, and every finding carrying a <code>learnUrl</code>.</li></ul><h2 id="_7-hard-rules" tabindex="-1">7. Hard rules <a class="header-anchor" href="#_7-hard-rules" aria-label="Permalink to &quot;7. Hard rules&quot;">​</a></h2><ul><li><strong>Escape everything.</strong> All rendered values pass through <code>esc()</code>. Resource names, tags and descriptions are attacker-influenceable tenant data in a file that gets emailed to executives.</li><li><strong>No external requests, ever.</strong> Inline CSS/JS/SVG only. A strict CSP blocks CDNs, and the report must render intact from a USB stick on an air-gapped laptop. This is why every figure is inline SVG rather than a diagram library.</li><li><strong>No vendor marketing on the report surface.</strong> Identity comes from the prompted company / client / title / classification block. Attribution belongs in the About panel, which print CSS hides.</li><li><strong>No secrets, subscription ids or tenant ids in committed fixtures.</strong></li></ul><h2 id="_8-adding-a-new-assessment-section" tabindex="-1">8. Adding a new assessment section <a class="header-anchor" href="#_8-adding-a-new-assessment-section" aria-label="Permalink to &quot;8. Adding a new assessment section&quot;">​</a></h2><ol><li>Ensure the assessment emits the §5 payload shape. Nothing else is required for it to appear — the generic renderer picks it up, it gets a landing tile and an <code>a-&lt;slug&gt;</code> page, nav includes it, and export covers it.</li><li><strong>Only if it needs richer treatment than the generic renderer:</strong> register a custom renderer against its slug. Registration is the extension point; editing the dispatch is not.</li><li>Add a contract test asserting the section renders at all three view depths and survives an empty payload.</li><li>The diagram overlap checker must pass (<code>tests/ReactReport.DiagramOverlap.Tests.ps1</code>).</li></ol><h2 id="_9-verification-—-how-a-section-is-accepted" tabindex="-1">9. Verification — how a section is accepted <a class="header-anchor" href="#_9-verification-—-how-a-section-is-accepted" aria-label="Permalink to &quot;9. Verification — how a section is accepted&quot;">​</a></h2><p>Rendering without error is not acceptance. A section is done when:</p><ul><li>[ ] <strong>the register is complete</strong> — every check listed, a gap block for every fail, every manual check listed with its question (asserted by the completeness gate in <code>tests/Report.PerAssessmentContract.Tests.ps1</code>);</li><li>[ ] it renders at all three view depths, and the three are materially different;</li><li>[ ] it renders in both light and dark themes;</li><li>[ ] it renders from an <strong>empty</strong> payload without throwing;</li><li>[ ] every score displays its formula, denominator and exclusions;</li><li>[ ] findings name real resources, or state in words why there is nothing to name;</li><li>[ ] every finding carries a working <code>learnUrl</code>;</li><li>[ ] at least one figure, drawn by the kernel, passing the overlap checker;</li><li>[ ] it survives Markdown / JSON / CSV / Print / standalone-HTML export with content intact;</li><li>[ ] <strong>a human has opened the artefact.</strong> A non-zero byte count is not evidence — the &quot;0 empty artefacts&quot; gate once passed green while the dashboard was blank.</li></ul>`,37)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
